cat > /tmp/adv20/fuzz.js <<'JS'
const AL='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function encInt(i){let s='';while(i>0n){s=AL[Number(i%58n)]+s;i/=58n;}return s;}
function b58encode(buf){let nz=0;while(nz<buf.length&&buf[nz]===0)nz++;let acc=0n;for(const b of buf)acc=acc*256n+BigInt(b);return '1'.repeat(nz)+(acc===0n?'':encInt(acc));}
let seed=12345; function rnd(){seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff;}
const rows=[];
for(let t=0;t<60;t++){
  const len=1+Math.floor(rnd()*8); let cps=[];
  for(let i=0;i<len;i++){
    const r=rnd();
    let cp;
    if(r<0.3) cp=0x21+Math.floor(rnd()*0x5e);            // printable ascii (no space/NUL)
    else if(r<0.6) cp=0x80+Math.floor(rnd()*0x780);       // 2-byte
    else if(r<0.85) cp=0x800+Math.floor(rnd()*0xf800);    // 3-byte, may hit surrogates
    else cp=0x10000+Math.floor(rnd()*0xf0000);            // 4-byte
    if(cp>=0xd800&&cp<=0xdfff) cp=0x2000+ (cp&0xff);      // avoid surrogates
    cps.push(cp);
  }
  const s=String.fromCodePoint(...cps);
  const b=Buffer.from(s,'utf8');
  if(b.includes(0)) continue;
  rows.push([b.toString('hex'), b58encode(b)].join('\t'));
}
console.log(rows.join('\n'));
